import { createCommandBus, lockMiddleware } from "@zudojs/cqrs";
import type { CqrsLock } from "@zudojs/cqrs";

const tails = new Map<string, Promise<void>>();
const lock: CqrsLock = {
  async acquire(key) {
    const previous = tails.get(key) ?? Promise.resolve();
    let release!: () => void;
    tails.set(key, previous.then(() => new Promise<void>((resolve) => (release = resolve))));
    await previous;
    return () => release();
  },
};
const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

for (const locked of [false, true]) {
  const middleware = locked ? [lockMiddleware(lock, { key: (r) => `order:${(r as { orderId?: string }).orderId}` })] : [];
  const bus = createCommandBus({ middleware });
  const log: string[] = [];
  bus.register("CancelOrder", async (c: { type: "CancelOrder"; orderId: string; tab: string }) => {
    log.push(`${c.tab} reads`);
    await wait(10);
    log.push(`${c.tab} writes`);
  });
  await Promise.all([
    bus.execute({ type: "CancelOrder", orderId: "ORD-1", tab: "A" }),
    bus.execute({ type: "CancelOrder", orderId: "ORD-1", tab: "B" }),
  ]);
  console.log(locked ? "locked:  " : "unlocked:", log.join(", "));
}

