function customerStats(events) {
  const stats = {};
  const placed = new Map();
  for (const event of events) {
    if (event.type === "order.placed") {
      placed.set(event.orderId, event);
      const s = stats[event.customerId] ?? { orders: 0, spentKobo: 0 };
      stats[event.customerId] = { orders: s.orders + 1, spentKobo: s.spentKobo + event.totalKobo };
    } else if (event.type === "order.cancelled") {
      const order = placed.get(event.orderId);
      if (!order) continue;
      const s = stats[order.customerId];
      stats[order.customerId] = { orders: s.orders - 1, spentKobo: s.spentKobo - order.totalKobo };
    }
  }
  return stats;
}

