function placeOrder(state, customerId, orderId, lines) {
  const existing = state.orders.get(orderId);
  if (existing) {
    if (existing.customerId !== customerId) throw new Error("taken");
    return existing.result;
  }
  for (const line of lines) {
    const product = state.products.get(line.sku);
    if (product.stock < line.qty) throw new Error(`only ${product.stock} of ${line.sku} left`);
  }
  let totalKobo = 0;
  for (const line of lines) {
    const product = state.products.get(line.sku);
    product.stock -= line.qty;
    totalKobo += product.priceKobo * line.qty;
  }
  const result = { orderId, totalKobo };
  state.orders.set(orderId, { customerId, result });
  state.outbox.push({ type: "order.placed", orderId, version: 1 });
  return result;
}

