async function readAfterWrite(get, minVersion, maxTries) {
  let tries = 0;
  let response;
  do {
    if (tries > 0) await new Promise((resolve) => setTimeout(resolve, 10));
    response = await get(minVersion);
    tries++;
  } while (response.status === 503 && tries < maxTries);
  return { tries, status: response.status };
}

let calls = 0;
